import json
import re
from typing import List, Dict

class EnterpriseRecursiveChunker:
    def __init__(self, max_chunk_tokens: int = 60, overlap_tokens: int = 15):
        self.max_tokens = max_chunk_tokens
        self.overlap = overlap_tokens
        self.separators = ['\n\n', '\n', '. ', ' ']

    def split_text(self, text: str) -> List[Dict]:
        raw_chunks = self._recursive_split(text, self.separators)
        final_chunks = []

        for idx, chunk_text in enumerate(raw_chunks):
            tokens = chunk_text.strip().split()
            if not tokens:
                continue
            final_chunks.append({
                'chunk_id': f'CHK-{idx+1:03d}',
                'token_count': len(tokens),
                'content': ' '.join(tokens)
            })
        return final_chunks

    def _recursive_split(self, text: str, separators: List[str]) -> List[str]:
        tokens = text.split()
        if len(tokens) <= self.max_tokens:
            return [text.strip()] if text.strip() else []

        if not separators:
            # Base case: split by token slice
            return self._split_by_tokens(tokens)

        sep = separators[0]
        remaining_seps = separators[1:]
        splits = text.split(sep)

        chunks = []
        current_segment = ''

        for s in splits:
            candidate = (current_segment + sep + s) if current_segment else s
            if len(candidate.split()) <= self.max_tokens:
                current_segment = candidate
            else:
                if current_segment:
                    chunks.append(current_segment.strip())
                if len(s.split()) > self.max_tokens:
                    # Recursive breakdown with next separator level
                    chunks.extend(self._recursive_split(s, remaining_seps))
                    current_segment = ''
                else:
                    current_segment = s

        if current_segment:
            chunks.append(current_segment.strip())
        return chunks

    def _split_by_tokens(self, tokens: List[str]) -> List[str]:
        chunks = []
        step = max(1, self.max_tokens - self.overlap)
        for i in range(0, len(tokens), step):
            slice_tokens = tokens[i:i + self.max_tokens]
            chunks.append(' '.join(slice_tokens))
        return chunks

# Execution: Recursive chunking on an enterprise treasury risk policy document
corporate_policy = (
    "SECTION 4: TREASURY RISK GOVERNANCE\n\n"
    "All foreign exchange transactions exceeding 100,000 USD require dual authorization by the Corporate Treasurer "
    "and Chief Risk Officer. Wire disbursements must be initiated via SWIFT MT103 protocols with end-to-end cryptographic hashing.\n\n"
    "SECTION 5: EMERGENCY LIQUIDITY PROTOCOLS\n\n"
    "In the event of a tier-1 banking counterparty collapse, treasury officers are authorized to sweep commercial paper "
    "balances into sovereign treasury bill accounts within sixty minutes. Daily reporting must be submitted to the Board Audit Committee."
)

chunker = EnterpriseRecursiveChunker(max_chunk_tokens=35, overlap_tokens=8)
chunks = chunker.split_text(corporate_policy)
print(json.dumps({
    'document_total_words': len(corporate_policy.split()),
    'total_chunks_produced': len(chunks),
    'chunks': chunks
}, indent=2))

