import json
from collections import defaultdict, deque
from typing import List, Dict, Tuple, Set

class RelationalReasoningComparator:
    def __init__(self):
        # Simulated vector store: document_id -> (text, embedding_concept)
        self.vector_store = {}
        # Knowledge graph: adjacency list entity -> list of (relation, target_entity)
        self.graph = defaultdict(list)

    def add_document_and_triplet(self, doc_id: str, text: str, concept: str, triplet: Tuple[str, str, str]):
        self.vector_store[doc_id] = {'text': text, 'concept': concept}
        subj, pred, obj = triplet
        self.graph[subj].append((pred, obj))

    def simulate_vector_search(self, query_concept: str) -> List[str]:
        # Vector search only retrieves documents matching the exact query concept
        retrieved = []
        for doc_id, data in self.vector_store.items():
            if data['concept'] == query_concept:
                retrieved.append(doc_id)
        return retrieved

    def execute_multi_hop_traversal(self, start_entity: str, target_relation_type: str, max_depth: int = 3) -> List[List[str]]:
        # Breadth-first search traversing multi-hop ownership/licensing paths
        paths = []
        queue = deque([([start_entity], start_entity, 0)])

        while queue:
            current_path, current_node, depth = queue.popleft()
            if depth >= max_depth:
                continue

            for relation, neighbor in self.graph[current_node]:
                new_path = current_path + [f'--({relation})-->', neighbor]
                if relation == target_relation_type:
                    paths.append(new_path)
                queue.append((new_path, neighbor, depth + 1))
        return paths

# Execution: Comparing Vector Search vs Graph Traversal on Corporate Sanctions Exposure
engine = RelationalReasoningComparator()

# Document 1: Alpha Corp owns Beta Holdings
engine.add_document_and_triplet('DOC-01', 'Alpha Corp acquired 70% equity stake in Beta Holdings.', 'ALPHA_CORP_INVESTMENT', ('Alpha_Corp', 'OWNS_EQUITY', 'Beta_Holdings'))
# Document 2: Beta Holdings licenses IP from Gamma Technologies
engine.add_document_and_triplet('DOC-02', 'Beta Holdings secured exclusive patent license from Gamma Technologies.', 'BETA_HOLDINGS_LICENSING', ('Beta_Holdings', 'LICENSES_PATENT', 'Gamma_Tech'))
# Document 3: Gamma Tech is under trade sanctions
engine.add_document_and_triplet('DOC-03', 'Gamma Technologies designated on Federal International Sanctions List.', 'SANCTIONS_REGULATORY_ALERT', ('Gamma_Tech', 'SUBJECT_TO', 'Federal_Sanctions'))

# Query: Does Alpha Corp have exposure to Federal Sanctions?
vector_hits = engine.simulate_vector_search('ALPHA_CORP_INVESTMENT')
graph_paths = engine.execute_multi_hop_traversal('Alpha_Corp', 'SUBJECT_TO', max_depth=4)

comparison_report = {
    'investigative_query': 'Does Alpha Corp have indirect exposure to Federal Sanctions?',
    'vector_search_results': {
        'retrieved_documents': vector_hits,
        'sanctions_detected': False,
        'failure_diagnosis': 'Vector search isolated DOC-01 and completely missed DOC-03 because DOC-03 shares zero semantic or lexical overlap with Alpha Corp.'
    },
    'graph_traversal_results': {
        'multi_hop_paths_discovered': graph_paths,
        'sanctions_detected': len(graph_paths) > 0,
        'provenance_trail': ' -> '.join(graph_paths[0]) if graph_paths else ''
    }
}
print(json.dumps(comparison_report, indent=2))

